-- Datos iniciales de PET FOOD. Generado por scripts/generate-data.mjs.
-- Ejecutar después de la migración: supabase db push / SQL Editor.
-- Cada fila conserva el objeto original del scraping en datos_originales (jsonb).

on conflict (slug) do update set
  nombre = excluded.nombre,
  categoria = excluded.categoria,
  precio = excluded.precio,
  moneda = excluded.moneda,
  imagen_url = excluded.imagen_url,
  enlace = excluded.enlace,
  vendedor = excluded.vendedor,
  calificacion = excluded.calificacion,
  total_calificaciones = excluded.total_calificaciones,
  cuotas = excluded.cuotas,
  envio = excluded.envio,
  envio_desde = excluded.envio_desde,
  descuento = excluded.descuento,
  etiqueta = excluded.etiqueta,
  promocion = excluded.promocion,
  promocion_url = excluded.promocion_url,
  destacado = excluded.destacado,
  datos_originales = excluded.datos_originales,
  activo = true,
  updated_at = now();
